/**
 * Claims drift lock — pattern counts.
 *
 * .claims.json is generated by text-parsing the rule sources
 * (scripts/claims/generators/eval-rules.mjs). That counter once shipped
 * 12/14/18 where the runtime truth was 10/13/17 (trailing commas counted as
 * separators; prose commas inside comments counted as elements) — and the
 * claims-alignment CI couldn't catch it because generator and file agreed
 * with each other about the wrong numbers.
 *
 * This suite breaks that closed loop by anchoring every layer to the RUNTIME
 * arrays: generator output === array.length === .claims.json === the counts
 * quoted in rule descriptions.
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { HALLUCINATION_MARKERS, noHallucinationMarkers } from '../src/eval/rules/relevance.js';
import { INJECTION_PATTERNS, PII_PATTERNS, noInjectionPatterns } from '../src/eval/rules/safety.js';
// @ts-ignore — plain .mjs module, no type declarations needed for a test
import { countTopLevelElements, generate } from '../scripts/claims/generators/eval-rules.mjs';

describe('countTopLevelElements (the text counter itself)', () => {
  it('does not count a trailing comma as an extra element', () => {
    expect(countTopLevelElements("'a', 'b', 'c',\n")).toBe(3);
  });

  it('ignores commas inside line and block comments', () => {
    expect(
      countTopLevelElements(`
        // a comment, with a comma, or two
        'a',
        /* block, comment */
        'b',
      `),
    ).toBe(2);
  });

  it('treats regex literals as opaque, including classes with slashes and braces', () => {
    expect(
      countTopLevelElements(`
        { name: 'X', pattern: /a{1,3}[\\/]b/i },
        { name: 'Y', pattern: /(?:c|d){2,}/ },
      `),
    ).toBe(2);
  });

  it('handles escaped quotes inside string elements', () => {
    expect(countTopLevelElements("'i don\\'t, ever', 'plain'")).toBe(2);
  });
});

describe('claims counts match runtime truth', () => {
  const claims = JSON.parse(readFileSync(resolve(__dirname, '..', '.claims.json'), 'utf-8')) as {
    evalRules: { piiPatterns: number; injectionPatterns: number; hallucinationMarkers: number };
  };

  it('generator output equals the runtime arrays', async () => {
    const out = (await generate()) as {
      piiPatterns: number;
      injectionPatterns: number;
      hallucinationMarkers: number;
    };
    expect(out.piiPatterns).toBe(PII_PATTERNS.length);
    expect(out.injectionPatterns).toBe(INJECTION_PATTERNS.length);
    expect(out.hallucinationMarkers).toBe(HALLUCINATION_MARKERS.length);
  });

  it('.claims.json equals the runtime arrays', () => {
    expect(claims.evalRules.piiPatterns).toBe(PII_PATTERNS.length);
    expect(claims.evalRules.injectionPatterns).toBe(INJECTION_PATTERNS.length);
    expect(claims.evalRules.hallucinationMarkers).toBe(HALLUCINATION_MARKERS.length);
  });

  it('rule descriptions that quote a count quote the real one', () => {
    expect(noInjectionPatterns.description).toContain(`${INJECTION_PATTERNS.length} patterns`);
    // The hallucination rule describes its mechanism, not a number — assert it
    // stays that way or names the true count.
    const desc = noHallucinationMarkers.description;
    const quoted = desc.match(/\b(\d+)\b/);
    if (quoted) expect(Number(quoted[1])).toBe(HALLUCINATION_MARKERS.length);
  });
});

describe('public .well-known/mcp.json matches the truthbase', () => {
  const claims = JSON.parse(readFileSync(resolve(__dirname, '..', '.claims.json'), 'utf-8')) as {
    mcpTools: { names: string[] };
    version: { mcpServer: string };
  };
  const manifest = JSON.parse(
    readFileSync(resolve(__dirname, '..', 'website', 'public', '.well-known', 'mcp.json'), 'utf-8'),
  ) as { version: string; tools: Array<{ name: string }>; install: { claude_desktop: { mcpServers: Record<string, unknown> } } };

  it('lists every shipped tool, no more, no fewer (once listed only 3 of 9)', () => {
    const manifestNames = manifest.tools.map(t => t.name).sort();
    expect(manifestNames).toEqual([...claims.mcpTools.names].sort());
  });

  it('advertises the shipped version and the canonical server key', () => {
    expect(manifest.version).toBe(claims.version.mcpServer);
    expect(Object.keys(manifest.install.claude_desktop.mcpServers)).toEqual(['iris-eval']);
  });
});
